{
  "components": [
    {
      "type": "condition",
      "quote": "Within two months after the conclusion of the consultation of public authorities",
      "gist": "Timeframe for SFOE to petition Federal Council"
    },
    {
      "type": "obligation",
      "quote": "the SFOE petitions the Federal Council to designate the planning corridor and applicable transmission technology",
      "gist": "SFOE must petition Federal Council to designate corridor and transmission tech"
    },
    {
      "type": "claim",
      "quote": "The procedure culminates in a detailed plan in which the Federal Council defines a corridor for the transmission line project and specifies the type of transmission technology to be used (overhead lines or underground cables)",
      "gist": "Procedure results in a binding detailed plan defining corridor and transmission technology"
    },
    {
      "type": "claim",
      "quote": "The detailed plan is binding for the entity submitting the application, as well as for the federal, cantonal and communal authorities",
      "gist": "Detailed plan is legally binding on all relevant authorities"
    },
    {
      "type": "claim",
      "quote": "Appeals against decisions taken by the Federal Council within the scope of the sectoral plan procedure are not possible",
      "gist": "No appeals allowed against Federal Council decisions in this procedure"
    }
  ]
}
